-- =============================================================
-- Catálogo geográfico: países, provincias (1er nivel) y distritos (2do nivel)
-- Fuente países/provincias: ISO 3166-1 / ISO 3166-2 vía countries-states-cities-database
--   (github.com/dr5hn/countries-states-cities-database, licencia ODbL)
-- Distritos de Panamá: división político-administrativa vigente (verificar con INEC)
-- Versión para PostgreSQL 12+ (UTF-8)
-- Uso: psql -U usuario -d base -f catalogo_geografico_postgres.sql
--
-- YA APLICADO (ver migrar-provincia-a-catalogo-paises.sql en esta misma
-- carpeta): la tabla "pais" que este script crea fue reconciliada con
-- public.catalogo_paises (que ya existía, con CRUD admin y columnas
-- nacionalidad/moneda/idioma_oficial/activo) y luego eliminada; provincia.
-- pais_id ahora referencia catalogo_paises(id). NO reejecutar este script
-- tal cual en esta base de datos: su DROP TABLE borraría provincia/distrito
-- ya poblados y recrearía "pais" como catálogo duplicado. Se conserva aquí
-- solo como registro histórico de la fuente de datos.
-- =============================================================

SET client_encoding = 'UTF8';

BEGIN;

DROP TABLE IF EXISTS distrito;
DROP TABLE IF EXISTS provincia;
DROP TABLE IF EXISTS pais;

CREATE TABLE pais (
    id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_iso2     CHAR(2)      NOT NULL UNIQUE,
    codigo_iso3     CHAR(3)      NOT NULL UNIQUE,
    codigo_numerico CHAR(3),
    nombre          VARCHAR(100) NOT NULL,
    nombre_ingles   VARCHAR(100) NOT NULL,
    codigo_telefono VARCHAR(20),
    moneda          CHAR(3),
    region          VARCHAR(50)
);

CREATE TABLE provincia (
    id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    pais_id       INTEGER          NOT NULL,
    codigo_iso    VARCHAR(10),
    nombre        VARCHAR(150) NOT NULL,
    nombre_ingles VARCHAR(150) NOT NULL,
    tipo          VARCHAR(60),
    CONSTRAINT fk_provincia_pais FOREIGN KEY (pais_id) REFERENCES pais(id) ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE distrito (
    id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    provincia_id  INTEGER          NOT NULL,
    codigo_iso    VARCHAR(10),
    nombre        VARCHAR(150) NOT NULL,
    tipo          VARCHAR(60),
    CONSTRAINT fk_distrito_provincia FOREIGN KEY (provincia_id) REFERENCES provincia(id) ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE INDEX ix_provincia_pais ON provincia(pais_id);
CREATE INDEX ix_distrito_provincia ON distrito(provincia_id);
CREATE INDEX ix_provincia_nombre ON provincia(nombre);
CREATE INDEX ix_distrito_nombre ON distrito(nombre);

COMMENT ON TABLE pais IS 'Países según ISO 3166-1';
COMMENT ON TABLE provincia IS 'Divisiones de primer nivel (ISO 3166-2)';
COMMENT ON TABLE distrito IS 'Divisiones de segundo nivel';

